set -euo pipefail

cd "$(dirname "$0")/.."
OUT=$(mktemp -d)
trap 'rm -rf "$OUT"' EXIT

sed 's/^import TailscaleKit$//' App/Workspace/WorkspaceStore.swift > "$OUT/store.swift"
cp scripts/test-workspace-store.swift "$OUT/main.swift"
