        -o "$OUT/workspace-store-tests" > "$OUT/build.log" 2>&1; then
    cat "$OUT/build.log" >&2
    echo "error: the workspace store host tests do not compile" >&2
    exit 1
fi
"$OUT/workspace-store-tests"
